/* Recorded from the running application by test/transcripts.e2e-spec.ts. Do not edit: a test records again and compares. */
window.TRANSCRIPTS = {
  "ingest": "<span class=\"tok-dim\"># A phone comes out of a tunnel with six readings: three good, one with no GPS fix (0, 0), one stamped two hours in the future, one older than the retention window.</span>\n<span class=\"tok-k\">→ POST /v1/pings   (6 readings)</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;accepted&quot;: 3,\n  &quot;duplicates&quot;: 0,\n  &quot;rejected&quot;: [\n    {\n      &quot;index&quot;: 3,\n      &quot;reason&quot;: &quot;bad_coordinate&quot;\n    },\n    {\n      &quot;index&quot;: 4,\n      &quot;reason&quot;: &quot;future&quot;\n    },\n    {\n      &quot;index&quot;: 5,\n      &quot;reason&quot;: &quot;too_old&quot;\n    }\n  ],\n  &quot;position_updated&quot;: true\n}\n\n<span class=\"tok-dim\"># The phone did not see the answer and sends the same batch again. Nothing is stored twice.</span>\n<span class=\"tok-k\">→ POST /v1/pings   (the same 6 readings)</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;accepted&quot;: 0,\n  &quot;duplicates&quot;: 3,\n  &quot;rejected&quot;: [\n    {\n      &quot;index&quot;: 3,\n      &quot;reason&quot;: &quot;bad_coordinate&quot;\n    },\n    {\n      &quot;index&quot;: 4,\n      &quot;reason&quot;: &quot;future&quot;\n    },\n    {\n      &quot;index&quot;: 5,\n      &quot;reason&quot;: &quot;too_old&quot;\n    }\n  ],\n  &quot;position_updated&quot;: false\n}\n\n<span class=\"tok-dim\"># A reading older than the newest one arrives late. It is kept in the history, but the vehicle does not move backwards.</span>\n<span class=\"tok-k\">→ POST /v1/pings   (1 reading, 20 minutes old)</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;accepted&quot;: 1,\n  &quot;duplicates&quot;: 0,\n  &quot;rejected&quot;: [],\n  &quot;position_updated&quot;: false\n}\n\n<span class=\"tok-dim\"># A body that names a driver is refused whole. The driver comes from the token, never from the request.</span>\n<span class=\"tok-k\">→ POST /v1/pings   (a reading with a driver_id)</span>\n<span class=\"tok-bad\">← 400</span>\n{\n  &quot;error&quot;: {\n    &quot;code&quot;: &quot;VALIDATION_FAILED&quot;,\n    &quot;message&quot;: &quot;Request validation failed&quot;,\n    &quot;details&quot;: {\n      &quot;issues&quot;: [\n        {\n          &quot;path&quot;: &quot;pings.0&quot;,\n          &quot;message&quot;: &quot;Unrecognized key: \\&quot;driver_id\\&quot;&quot;\n        }\n      ]\n    }\n  }\n}",
  "arrival": "<span class=\"tok-dim\"># The trip is under way to Elm Crossing (a 150 m radius). One accurate fix inside the radius could be GPS jitter, so it is not an arrival.</span>\n<span class=\"tok-k\">→ POST /v1/pings   (1 accurate fix inside)</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;accepted&quot;: 1,\n  &quot;duplicates&quot;: 0,\n  &quot;rejected&quot;: [],\n  &quot;position_updated&quot;: true\n}\n{\n  &quot;status&quot;: &quot;IN_TRANSIT&quot;,\n  &quot;arrived_at&quot;: null\n}\n\n<span class=\"tok-dim\"># A second fix inside, but one that admits ±400 m of error, is too vague to confirm anything.</span>\n<span class=\"tok-k\">→ POST /v1/pings   (1 fix inside, accuracy 400 m)</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;accepted&quot;: 1,\n  &quot;duplicates&quot;: 0,\n  &quot;rejected&quot;: [],\n  &quot;position_updated&quot;: true\n}\n{\n  &quot;status&quot;: &quot;IN_TRANSIT&quot;,\n  &quot;arrived_at&quot;: null\n}\n\n<span class=\"tok-dim\"># A second accurate fix inside the radius: two in a row. The trip has arrived.</span>\n<span class=\"tok-k\">→ POST /v1/pings   (1 accurate fix inside)</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;accepted&quot;: 1,\n  &quot;duplicates&quot;: 0,\n  &quot;rejected&quot;: [],\n  &quot;position_updated&quot;: true\n}\n{\n  &quot;status&quot;: &quot;IN_TRANSIT&quot;,\n  &quot;arrived_at&quot;: &quot;&lt;time-1&gt;&quot;\n}\n\n<span class=\"tok-dim\"># The same fixes arrive again, from a retry. The arrival is stamped once, with a conditional update, and keeps its time.</span>\n<span class=\"tok-k\">→ POST /v1/pings   (all three fixes again)</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;accepted&quot;: 0,\n  &quot;duplicates&quot;: 3,\n  &quot;rejected&quot;: [],\n  &quot;position_updated&quot;: false\n}\n{\n  &quot;status&quot;: &quot;IN_TRANSIT&quot;,\n  &quot;arrived_at&quot;: &quot;&lt;time-1&gt;&quot;\n}",
  "alerts": "<span class=\"tok-dim\"># The phone reports once, then goes quiet.</span>\n<span class=\"tok-k\">→ POST /v1/pings   (1 reading)</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;accepted&quot;: 1,\n  &quot;duplicates&quot;: 0,\n  &quot;rejected&quot;: [],\n  &quot;position_updated&quot;: true\n}\n\n<span class=\"tok-dim\"># Sixteen minutes later the scheduled evaluator (the worker runs it every 30 seconds) compares the facts with the open alerts.</span>\n<span class=\"tok-k\">⟳ worker: alerts.evaluate()</span>\n{\n  &quot;evaluated&quot;: 1,\n  &quot;opened&quot;: 1,\n  &quot;cleared&quot;: 0\n}\n[\n  {\n    &quot;kind&quot;: &quot;no_signal&quot;,\n    &quot;status&quot;: &quot;open&quot;,\n    &quot;detail&quot;: {\n      &quot;never_reported&quot;: false,\n      &quot;silent_minutes&quot;: 16\n    },\n    &quot;opened_at&quot;: &quot;&lt;time-1&gt;&quot;,\n    &quot;cleared_at&quot;: null\n  }\n]\n\n<span class=\"tok-dim\"># It runs again, or three workers run it at once. A partial unique index allows one open alert per vehicle and kind, so nothing new opens.</span>\n<span class=\"tok-k\">⟳ worker: alerts.evaluate()</span>\n{\n  &quot;evaluated&quot;: 1,\n  &quot;opened&quot;: 0,\n  &quot;cleared&quot;: 0\n}\n\n<span class=\"tok-dim\"># The phone reports again. The next evaluation sees a recent position and clears the alert, keeping when it opened.</span>\n<span class=\"tok-k\">→ POST /v1/pings   (1 reading)</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;accepted&quot;: 1,\n  &quot;duplicates&quot;: 0,\n  &quot;rejected&quot;: [],\n  &quot;position_updated&quot;: true\n}\n<span class=\"tok-k\">⟳ worker: alerts.evaluate()</span>\n{\n  &quot;evaluated&quot;: 1,\n  &quot;opened&quot;: 0,\n  &quot;cleared&quot;: 1\n}\n[\n  {\n    &quot;kind&quot;: &quot;no_signal&quot;,\n    &quot;status&quot;: &quot;cleared&quot;,\n    &quot;detail&quot;: {\n      &quot;never_reported&quot;: false,\n      &quot;silent_minutes&quot;: 16\n    },\n    &quot;opened_at&quot;: &quot;&lt;time-1&gt;&quot;,\n    &quot;cleared_at&quot;: &quot;&lt;time-2&gt;&quot;\n  }\n]",
  "queue": "<span class=\"tok-dim\"># A mobile unit holds 3 people. Five people join the queue (one request each; the first is shown).</span>\n<span class=\"tok-k\">→ POST /v1/units/&lt;unit&gt;/tickets   (guest-1)</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;id&quot;: &quot;&lt;id-1&gt;&quot;,\n  &quot;unit_id&quot;: &quot;&lt;id-2&gt;&quot;,\n  &quot;person_ref&quot;: &quot;guest-1&quot;,\n  &quot;service&quot;: &quot;loading&quot;,\n  &quot;priority&quot;: false,\n  &quot;status&quot;: &quot;waiting&quot;,\n  &quot;created_at&quot;: &quot;&lt;time-1&gt;&quot;,\n  &quot;called_at&quot;: null\n}\n\n<span class=\"tok-dim\"># The dispatcher calls the next five. One rule decides how many fit, with the unit row locked while it does.</span>\n<span class=\"tok-k\">→ POST /v1/units/&lt;unit&gt;/call-next   {&quot;count&quot;: 5}</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;called&quot;: [\n    &quot;guest-1&quot;,\n    &quot;guest-2&quot;,\n    &quot;guest-3&quot;\n  ],\n  &quot;capacity&quot;: 3,\n  &quot;reason&quot;: &quot;ok&quot;\n}\n{\n  &quot;on_board&quot;: 3,\n  &quot;free_places&quot;: 0,\n  &quot;tickets&quot;: [\n    &quot;guest-1: called&quot;,\n    &quot;guest-2: called&quot;,\n    &quot;guest-3: called&quot;,\n    &quot;guest-4: waiting&quot;,\n    &quot;guest-5: waiting&quot;\n  ]\n}\n\n<span class=\"tok-dim\"># Now somebody calls guest-4 by hand. A different entry point, the same rule.</span>\n<span class=\"tok-k\">→ POST /v1/tickets/&lt;ticket&gt;/call   (guest-4)</span>\n<span class=\"tok-bad\">← 409</span>\n{\n  &quot;error&quot;: {\n    &quot;code&quot;: &quot;UNIT_FULL&quot;,\n    &quot;message&quot;: &quot;The unit is full: 3 of 3 places are taken&quot;,\n    &quot;details&quot;: {\n      &quot;on_board&quot;: 3,\n      &quot;capacity&quot;: 3\n    }\n  }\n}\n\n<span class=\"tok-dim\"># One person is served and finishes. A place frees up, and the same call now works.</span>\n<span class=\"tok-k\">→ POST /v1/tickets/&lt;ticket&gt;/call   (guest-4)</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;person_ref&quot;: &quot;guest-4&quot;,\n  &quot;status&quot;: &quot;called&quot;\n}",
  "boundaries": "<span class=\"tok-dim\"># A dispatcher of another fleet asks for this fleet’s trip, and then for a trip that never existed. Same answer: the other fleet’s data does not exist for them.</span>\n<span class=\"tok-k\">→ GET /v1/trips/&lt;fleet A’s trip&gt;   (as fleet B)</span>\n<span class=\"tok-bad\">← 404</span>\n{\n  &quot;error&quot;: {\n    &quot;code&quot;: &quot;NOT_FOUND&quot;,\n    &quot;message&quot;: &quot;Trip not found&quot;\n  }\n}\n<span class=\"tok-k\">→ GET /v1/trips/&lt;no such trip&gt;   (as fleet B)</span>\n<span class=\"tok-bad\">← 404</span>\n{\n  &quot;error&quot;: {\n    &quot;code&quot;: &quot;NOT_FOUND&quot;,\n    &quot;message&quot;: &quot;Trip not found&quot;\n  }\n}\n\n<span class=\"tok-dim\"># The trip sheet is a PDF behind a signed link: an HMAC over the trip, the fleet and the expiry. The genuine link opens it.</span>\n<span class=\"tok-k\">→ GET &lt;the link&gt;</span>\n<span class=\"tok-ok\">← 200</span>\n(a PDF, content-type application/pdf)\n\n<span class=\"tok-dim\"># One character of the signature changed. The answer says nothing about why.</span>\n<span class=\"tok-k\">→ GET &lt;the link, one signature character changed&gt;</span>\n<span class=\"tok-bad\">← 403</span>\n{\n  &quot;error&quot;: {\n    &quot;code&quot;: &quot;INVALID_LINK&quot;,\n    &quot;message&quot;: &quot;This link is not valid&quot;\n  }\n}\n\n<span class=\"tok-dim\"># Past its expiry, a genuine link says so. Only someone holding a link the server really signed learns that.</span>\n<span class=\"tok-k\">→ GET &lt;the genuine link, after it expires&gt;</span>\n<span class=\"tok-bad\">← 410</span>\n{\n  &quot;error&quot;: {\n    &quot;code&quot;: &quot;LINK_EXPIRED&quot;,\n    &quot;message&quot;: &quot;This link has expired; ask for a new one&quot;\n  }\n}\n\n<span class=\"tok-dim\"># The road router returns a route with a vertex thousands of kilometres away. The application refuses it and the ETA says it fell back to a straight line.</span>\n<span class=\"tok-k\">→ GET /v1/fleet/snapshot   (router healthy)</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;eta&quot;: {\n    &quot;distanceKm&quot;: 14.1,\n    &quot;minutes&quot;: 17,\n    &quot;source&quot;: &quot;road&quot;,\n    &quot;speedBasis&quot;: &quot;router&quot;\n  },\n  &quot;router_breaker&quot;: &quot;closed&quot;\n}\n<span class=\"tok-k\">→ GET /v1/fleet/snapshot   (router answers with hostile geometry)</span>\n<span class=\"tok-ok\">← 200</span>\n{\n  &quot;eta&quot;: {\n    &quot;distanceKm&quot;: 10.3,\n    &quot;minutes&quot;: 10,\n    &quot;source&quot;: &quot;straight_line&quot;,\n    &quot;speedBasis&quot;: &quot;default&quot;\n  },\n  &quot;router_breaker&quot;: &quot;closed&quot;\n}"
};
